package com.mannvaasam.model;
import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*;
@Entity @Table(name="orders",indexes={@Index(name="idx_order_buyer",columnList="buyer_id"),@Index(name="idx_order_seller",columnList="seller_id"),@Index(name="idx_order_status",columnList="status")})
public class Order { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false,unique=true) public String orderNumber; @ManyToOne(optional=false) public User buyer; @ManyToOne(optional=false) public User seller; @OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true) public List<OrderItem> items=new ArrayList<>(); @Enumerated(EnumType.STRING) public OrderStatus status=OrderStatus.PLACED; @Enumerated(EnumType.STRING) public PaymentMethod paymentMethod; @Enumerated(EnumType.STRING) public PaymentStatus paymentStatus; @Column(nullable=false,precision=12,scale=2) public BigDecimal subtotal=BigDecimal.ZERO; @Column(nullable=false,precision=12,scale=2) public BigDecimal deliveryCharge=BigDecimal.ZERO; @Column(nullable=false,precision=12,scale=2) public BigDecimal total=BigDecimal.ZERO; public String shippingAddress,city,state,pincode; public Double latitude,longitude; public Integer estimatedDeliveryDays; public Instant createdAt=Instant.now(); public Instant updatedAt=Instant.now(); }